import java.util.Scanner;

public class Main {
    static int n, k, p;
    static int[][] cache_dp = new int[30][250005];
    static int[] factorials = new int[250005], inv_factorials = new int[250005];

    static int bin_pow(int base, int exp) {
        long res = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * cur) % p;
            cur = (cur * cur) % p;
            exp >>= 1;
        }
        return (int) res;
    }

    static int get_bit(int x) {
        return x & (-x);
    }

    static void precompute() {
        factorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorials[i] = (int) ((long) factorials[i - 1] * i % p);
        }
        inv_factorials[n] = bin_pow(factorials[n], p - 2);
        for (int i = n; i >= 1; i--) {
            inv_factorials[i - 1] = (int) ((long) inv_factorials[i] * i % p);
        }
    }

    static int compute(int index, int mask) {
        if (cache_dp[index][mask] != -1)
            return cache_dp[index][mask];
        if (mask == 0) {
            int res = factorials[n];
            for (int i = 1; i <= index; i++)
                res = (int) ((long) res * (k - i + 1) % p);
            return cache_dp[index][mask] = res;
        }
        int total = 0;
        int rem = mask - get_bit(mask);
        for (int subset = rem; subset != 0; subset = (subset - 1) & rem)
            total = (total + (long) inv_factorials[mask - subset] * compute(index + 1, subset) % p) % p;
        total = (total + (long) inv_factorials[mask] * compute(index + 1, 0) % p) % p;
        return cache_dp[index][mask] = total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        p = sc.nextInt();

        int answer = 1;
        for (int i = 1; i <= n; i++) {
            answer = (int) ((long) answer * k % p);
        }

        if (n % 2 == 0) {
            for (int i = 0; i < cache_dp.length; i++) {
                for (int j = 0; j < cache_dp[i].length; j++) {
                    cache_dp[i][j] = -1;
                }
            }
            precompute();
            answer = (answer - compute(0, n) + p) % p;
        }

        System.out.println(answer);
        sc.close();
    }
}
